1	/**
2	 * Watching a map arrive, and reading back what the screen did while it moved.
3	 *
4	 * **A growing map needs one thing a finished one does not**: several of the
5	 * claims made about it are about *moments*. *A rectangle stood before any claim
6	 * had arrived*, *a rectangle stood at the growing edge every step of the way*,
7	 * *the claims arrived one at a time*, *no likelihood appeared until the map was
8	 * whole* — each is true at some moments and false at others, and by the time an
9	 * assertion has been written the moment it was about is gone. Polling for one of
10	 * them races the run; asserting after it is over asserts about the wrong moment.
11	 *
12	 * So the page watches itself. Every change to the page is looked at — which is
13	 * every moment the screen was different — and what was on it is written down.
14	 * Nothing here sleeps, and nothing here can miss a moment a poll would have
15	 * stepped over.
16	 *
17	 * They live in a file of their own because **two** browser tests play a
18	 * recording and read the record back: `generate.spec.ts`, which watches an
19	 * ordinary run, and `lateLayout.spec.ts`, which watches one whose layout thread
20	 * was made to start late. A helper copied into a second file is a second helper:
21	 * the day one of them learns about a new way the screen can lie, only one test
22	 * would learn it.
23	 */
24	
25	import { expect, type Page } from "@playwright/test";
26	
27	/** The sentence the first screen's first card carries, as a reader would type it. */
28	export const THE_SENTENCE = "The Strait of Hormuz is going to open next week.";
29	
30	/**
31	 * How long a whole run is allowed to take before a test gives up on it.
32	 *
33	 * **A replay takes as long as its recording**, because the pacing is the
34	 * server's and the number of events is the file's — a twenty-proposal run is
35	 * four times the twenty seconds a five-proposal one takes, and neither number
36	 * is a test's to know. So the bound below is not a measurement and is not tuned
37	 * to a machine: it is generous on purpose, and exists only so that a run which
38	 * has genuinely stopped fails as a test rather than hanging.
39	 *
40	 * The default fifteen seconds is the wrong bound for exactly one thing —
41	 * waiting for a run to finish — and the right one everywhere else, so it is
42	 * named here and used there.
43	 */
44	export const A_WHOLE_RUN = 120_000;
45	
46	/** What watching a whole run saw. */
47	export interface WhatItSaw {
48	  /** True when, at some moment, a rectangle stood and not one claim had arrived. */
49	  readonly rectangleBeforeAnyClaim: boolean;
50	  /**
51	   * The words on the first rectangle, read at a moment when no claim had
52	   * arrived — so it is the one held open for the reader's own sentence and not
53	   * one of the frontier's, which carry *one step on from "…"*.
54	   *
55	   * Empty when no such moment was seen.
56	   */
57	  readonly firstRectangleSaid: string;
58	  /** The most rectangles that stood at once. */
59	  readonly mostRectangles: number;
60	  /**
61	   * True when, at some moment, two boxes on the map stood in the same place.
62	   *
63	   * The place they would share is the map's origin, where the hypothesis is:
64	   * a box the layout has not placed yet used to be drawn there, so every
65	   * arriving claim sat on top of the first one until the layout answered.
66	   */
67	  readonly everStacked: boolean;
68	  /**
69	   * How many rectangles stood at the moment each claim arrived, in order.
70	   *
71	   * The growing edge saying where the map is going, step by step, rather than
72	   * only at the start. **The last entry is allowed to be none**: the frontier
73	   * empties when the last claim closes, and no rectangle may stand where
74	   * nothing is coming.
75	   */
76	  readonly heldWhenEachClaimArrived: readonly number[];
77	  /**
78	   * How many claims were on the map, every time that number changed.
79	   *
80	   * The sequence rather than the largest of them: the largest is whatever the
81	   * map ended up with, which is a fact about the end and says nothing at all
82	   * about how the map got there. A map that appeared all at once and a map that
83	   * grew claim by claim have the same largest number and completely different
84	   * sequences.
85	   */
86	  readonly claimsWentOn: readonly number[];
87	  /**
88	   * How many claims were on the map the first time any likelihood appeared, and
89	   * how many appeared at that moment.
90	   *
91	   * Both are zero when none ever did. Together they are the statement that the
92	   * chips resolve **last** and **once**: the first number arrives when the map
93	   * is complete, and every other number arrives in the same breath.
94	   */
95	  readonly whenTheNumbersCame: { readonly claims: number; readonly numbers: number };
96	}
97	
98	/** Where the page keeps what it has seen of itself. */
99	declare global {
100	  interface Window {
101	    theRecord?: WhatItSaw & { rectangleBeforeAnyClaim: boolean };
102	    stopWatching?: () => void;
103	  }
104	}
105	
106	/**
107	 * What this copy of the server says it can play back without a key.
108	 *
109	 * Asked of the server rather than read off the screen: whether a test has
110	 * anything to do at all is a fact about the server, and reading it off the page
111	 * would make the skip depend on the very screen being tested.
112	 *
113	 * @param page The page to ask from, so the question goes to the server this run
114	 *   started and to no other.
115	 */
116	export async function whatCanBeReplayed(page: Page): Promise<{ example: string }[]> {
117	  const answer = await page.request.get("/api/readyz");
118	  const said = (await answer.json()) as { replayable?: { example: string }[] };
119	  return said.replayable ?? [];
120	}
121	
122	/**
123	 * Have the page start watching itself, before anything is asked for.
124	 *
125	 * **It is installed before the press**, and awaited, so that the very first
126	 * frame of the run is inside the record. Starting it after the press leaves the
127	 * one moment the first assertion is about — a rectangle standing with no claim
128	 * beside it — outside the window being watched, on a fast replay.
129	 *
130	 * @param page The page the map will be on.
131	 */
132	export async function startWatching(page: Page): Promise<void> {
133	  await page.evaluate(() => {
134	    const record = {
135	      rectangleBeforeAnyClaim: false,
136	      firstRectangleSaid: "",
137	      mostRectangles: 0,
138	      everStacked: false,
139	      heldWhenEachClaimArrived: [] as number[],
140	      claimsWentOn: [] as number[],
141	      whenTheNumbersCame: { claims: 0, numbers: 0 },
142	    };
143	    window.theRecord = record;
144	
145	    const look = (): void => {
146	      const held = document.querySelectorAll(".skeleton-tile").length;
147	      const claims = document.querySelectorAll(".tile").length;
148	      // A chip says on its own face whether it is showing a number or words,
149	      // and that is the marker to count: every chip renders a reading, and on
150	      // a growing map most of them are reading an absence out.
151	      const numbers = document.querySelectorAll('.belief-chip[data-reading="number"]').length;
152	
153	      if (held > 0 && claims === 0) {
154	        record.rectangleBeforeAnyClaim = true;
155	        // **Read here, and never again from the live page.** What the first
156	        // rectangle says is true of one moment: the moment after it is drawn
157	        // and before the first claim replaces it with the frontier's. Reading
158	        // it in a second round trip asks a screen that has moved on — and on a
159	        // cold machine the whole run can finish in between, so the rectangle is
160	        // not merely different, it is gone.
161	        record.firstRectangleSaid = document.querySelector(".skeleton-tile")?.textContent ?? "";
162	      }
163	      record.mostRectangles = Math.max(record.mostRectangles, held);
164	      if (record.claimsWentOn[record.claimsWentOn.length - 1] !== claims) {
165	        // What the growing edge was saying at the moment this claim arrived.
166	        if (claims > 0) {
167	          record.heldWhenEachClaimArrived.push(held);
168	        }
169	        record.claimsWentOn.push(claims);
170	      }
171	      // Two boxes in one place. The place they would share is the map's origin,
172	      // where a box the layout has not placed yet used to be drawn.
173	      const places = [...document.querySelectorAll(".react-flow__node")].map(
174	        (one) => (one as HTMLElement).style.transform,
175	      );
176	      if (new Set(places).size !== places.length) {
177	        record.everStacked = true;
178	      }
179	      if (numbers > 0 && record.whenTheNumbersCame.numbers === 0) {
180	        record.whenTheNumbersCame = { claims, numbers };
181	      }
182	    };
183	
184	    const watching = new MutationObserver(look);
185	    window.stopWatching = () => watching.disconnect();
186	    watching.observe(document.body, { subtree: true, childList: true, attributes: true });
187	    look();
188	  });
189	}
190	
191	/**
192	 * Stop watching, and read back what the page saw of itself.
193	 *
194	 * **It waits for nothing.** The waiting is done by the named signals around it,
195	 * which is where a test that has to give up belongs: a watcher that settled on a
196	 * signal of its own would hang until the whole test timed out on a run that
197	 * broke, and the failure a reader saw would be *"test timed out"* rather than
198	 * *"the run said it failed"*.
199	 *
200	 * @param page The page the map is on.
201	 */
202	export async function whatItSaw(page: Page): Promise<WhatItSaw> {
203	  return await page.evaluate(() => {
204	    window.stopWatching?.();
205	    return window.theRecord as WhatItSaw;
206	  });
207	}
208	
209	/**
210	 * Wait until the run is over, which is the receipt arriving and the map saying
211	 * why it stopped.
212	 *
213	 * Two signals rather than one, because they are two events: the receipt is what
214	 * the run cost and the closing line is why it ended, and a screen that had the
215	 * first and not the second would be read here as finished when it is not.
216	 *
217	 * **This is the one wait with a bound of its own**, and it is the one that needs
218	 * one: everything else is waiting for the page to catch up with something that
219	 * has already happened, where fifteen seconds is generous. This waits for a
220	 * whole recording to play, which takes as long as the recording is — see
221	 * `A_WHOLE_RUN`.
222	 *
223	 * @param page The page the map is on.
224	 */
225	export async function waitUntilItStops(page: Page): Promise<void> {
226	  await expect(page.locator(".receipt-strip")).toBeVisible({ timeout: A_WHOLE_RUN });
227	  await expect(page.locator(".done-line")).toBeVisible({ timeout: A_WHOLE_RUN });
228	  // Every rectangle goes when the likelihoods land: the set of claims still open
229	  // is empty by definition once the map is finished.
230	  await expect(page.locator(".skeleton-tile")).toHaveCount(0);
231	}
232	
233	/**
234	 * Every pair of boxes on the map that overlap. Empty is the only right answer.
235	 *
236	 * @param page The page the map is on.
237	 */
238	export async function boxesRunningIntoEachOther(page: Page): Promise<string[]> {
239	  return await page.locator(".react-flow__node").evaluateAll((boxes) => {
240	    const seen = boxes.map((box) => ({
241	      id: (box as HTMLElement).dataset.id ?? "?",
242	      at: box.getBoundingClientRect(),
243	    }));
244	    const found: string[] = [];
245	    for (let one = 0; one < seen.length; one += 1) {
246	      for (let other = one + 1; other < seen.length; other += 1) {
247	        const a = seen[one];
248	        const b = seen[other];
249	        if (
250	          a !== undefined &&
251	          b !== undefined &&
252	          a.at.left < b.at.right &&
253	          b.at.left < a.at.right &&
254	          a.at.top < b.at.bottom &&
255	          b.at.top < a.at.bottom
256	        ) {
257	          found.push(`${a.id} runs into ${b.id}`);
258	        }
259	      }
260	    }
261	    return found;
262	  });
263	}
